39: function makeGene(rng,i){let [name,role]=FUNCTIONS[i%FUNCTIONS.length], codonN=5+rng.int(8), coding='ATG';for(let j=1;j<codonN-1;j++)coding+=rng.pick(CODONS.slice(1));coding+='TAA';let intron='';for(let j=0;j<20+rng.int(35);j++)intron+='ATCG'[rng.int(4)];let exonStart=100+rng.int(140), promoter='TATAAA';let regulation=['constitutive','nutrient-responsive','stress-inducible','developmental'][rng.int(4)];return{id:`G${String(i+1).padStart(2,'0')}`,name,role,chromosome:1+rng.int(3),start:exonStart,end:exonStart+coding.length+intron.length+16,promoter,enhancer:rng.pick(['CAAT','GC-box','HSE','CRE']),coding,intron,regulation,activity:.34+rng.next()*.62,dominance:rng.pick(['dominant','recessive','additive']),mutation:null,epi:rng.next()*.14}}
40: function makeGenome(seed,source=null){let rng=new RNG(hashSeed(seed)),genes=source?source.genes.map(g=>({...g})):Array.from({length:8+rng.int(4)},(_,i)=>makeGene(rng,i));let noncoding='';for(let i=0;i<120;i++)noncoding+='ATCG'[rng.int(4)];return{id:`GX-${hashSeed(seed).toString(16).toUpperCase().slice(0,6)}`,seed,chromosomes:source?source.chromosomes:2+rng.int(3),genes,noncoding,sequence:'',generation:source?.generation||0,origin:source?.id||null,mutations:source?source.mutations||0:0}}
